        var labelName = $(this).val()+$(this).data('label_name');
        if (optionNewValue.includes(labelName)) {
          if(!$(this).prop('checked')){
            $(this).prop('checked', true);
          }
        }
      });
      //$(this).parent().append(unavailable_msg);
      var parentElement = $(this_clicked).parent('.js-product-option-form');
      const unavailableMessaging = document.querySelectorAll('.unavailableOptionTxt') || [];

      if (parentElement) {
        if (unavailableMessaging?.length > 0) {
          [...unavailableMessaging].forEach((item) => {
            item.remove();
          });
        }

        // append unavailable message if not already appended
        if (parentElement.find('.unavailableOptionTxt').length == 0) {
          parentElement.append(unavailable_msg);
        }
      }

      var prod_hadle = filteredProducts[0].url;
      var variant_id = filteredProducts[0].variant_id;
      var prod_available = filteredProducts[0].available;
      var product_id= filteredProducts[0].product_id;
      var product_sku = filteredProducts[0].product_sku;
      var product_title = filteredProducts[0].product_title;
      var product_type =  filteredProducts[0].product_type;
      var product_price = filteredProducts[0].product_price;
      var productcomPrice = filteredProducts[0].productcomPrice;
      var viewurl = filteredProducts[0].full_url;
      changeVariantAjax(viewurl, product_id, product_sku, product_title, product_type, product_price, productcomPrice,this_clicked);
      if(filteredProducts[0].available == 'true'){
        showCart();
      }else{
        hideCart();
      }
    }

    function showCart(){
      $(".show_atc a").show();
      $(".show_buy a").show();
      $(".hide---atc a").hide();
      $(".hide---atc span").hide();
      $(".free_shipping_msg").show();
      $(".free_shipping_msg_2").show();
      $("pickup-availability").css("display", "block");
      $(".four-buynow").addClass("four-atc");
      $(".applyforFinancing").show();
      $(".sticky-container").removeClass("outofstock_sc");
    }
    function hideCart(){
      $(".hide---atc a").show();
      $(".hide---atc span").show();
      $(".show_atc a").hide();
      $(".show_buy a").hide();
      $(".free_shipping_msg").hide();
      $(".free_shipping_msg_2").hide();
      $("pickup-availability").css("display", "none");
      $(".four-buynow").removeClass("four-atc");
      $(".applyforFinancing").hide();
      $(".sticky-container").addClass("outofstock_sc");
    }
    var shop_url = "https://www.digimap.co.id";
    function changeVariantAjax(viewurl, product_id, product_sku, product_title, product_type, product_price, productcomPrice,this_clicked){
      var option1=this_clicked.siblings("label:first").attr("data-option");
      var option_color = this_clicked.attr("data-color_present");
      var productRecommendationsCurrentId = '#frequent-list_current-product';
      var productRecommendationsCurrentEl = $(productRecommendationsCurrentId);
      var productRecommendationsView = 'product-recommendations-view';

      resetErrors();

      var sectionIds = ['template--18725171265687__main', 'product-ajax-data'];
      $('.js-collapsecon').each(function() {
        var sectionId = $(this).attr('id')?.split('shopify-section-')[1] || null;
        if (sectionId) {
          sectionIds.push(sectionId);
        }
      });

      $.ajax({
        type: 'GET',
        url: viewurl + `?sections=${sectionIds.join(',')}`,
        beforeSend: function() {
          $('variant-radios1').addClass('var_radio_point_none');
          // $('.loader_pdp_variant_switch').addClass('active');
          $("pickup-availability").each(function(index,item){
            item.renderLoading();
          });
        },
        success: function(resp) {
          var itemData = Object.values(resp).join('');

          // remove the store locator from the response so it doesn't fetch the API each time jQuery is called
          var itemDataNode = new DOMParser().parseFromString(itemData, 'text/html');
          var newStoreLocator = itemDataNode.querySelector('my-store-locator');
          if (newStoreLocator) {
            newStoreLocator.remove();
          }

          itemData = itemDataNode;
          var newPickupAvailability = $(itemData).find('pickup-availability').first();
          var productId = newPickupAvailability.attr("data-product-id");
          var selectedOptions = newPickupAvailability.attr("data-selected-options");
          var nmpTest = document.querySelector('.js-nmp-test-mode') || null;
          var nmpTrigger = itemData?.querySelector('.js-net-monthly-pricing-pdp-trigger') || null;
          $("pickup-availability").attr("data-product-id",productId);
          $("pickup-availability").attr("data-selected-options",selectedOptions);
          $(".js-store-locator-product-info").html($(itemData).find('.js-store-locator-product-info').html());
          // init store locator again with new variant details
          var storeLocator = document.querySelector('my-store-locator');
          if (storeLocator) {
            storeLocator.init();
          }

          if (nmpTrigger && nmpTest) {
            var { product: productHandle } = nmpTrigger.dataset || {};

            if (productHandle) {
              // init nmp test mode with new variant details
              nmpTest.getNMPTerms(productHandle);
            }
          }

          $(document).attr('title', $(itemData).find('#page_title').val());
          window.history.replaceState("", "", viewurl);
          //var product_list = $("#product_list").val();
          $(".product__title").html($(itemData).find('.product__title').html());
          $(".color-name").html($(itemData).find('.color-name').html());
          $(".band-color-name").html($(itemData).find('.band-color-name').html());
          $(".skuAndBarcode").html($(itemData).find('.skuAndBarcode').html());
          $(".product__preorder-message").html($(itemData).find('.product__preorder-message').html());
          $(".pricestyle").html($(itemData).find('.pricestyle').html());
          $(itemData).find(".product__info-container .product__accordion").each(function(index,item){
            // var isOpen=$(".product__info-container").find(".product__accordion").eq(index).find("details").attr("open");
            if(index==0){
              $(item).find("details").attr("open","open");
            }
            $(".product__info-container").find(".product__accordion").eq(index).html($(item).html());
          });

          $(".product-custom-media").html($(itemData).find('.product-custom-media').html());
          $(".product-media-modal__content").html($(itemData).find('.product-media-modal__content').html());
          $('.product__media-gallery').prepend('<div class="mobile_media_slider"><ul class="slider_media"></ul></div>');
          $('.slider_media').html('');
          //  $("#product_list").val(product_list);
          $(".common_medias").each(function(){
            var data = $(this).find('.product__media').html()
            $('.slider_media').append('<li>'+data+'</li>');
          });
          $('.slider_media').slick({
            prevArrow: `
              <button class="slide-arrow prev-arrow">
                <span class="screenreader">Previous</span>
                <svg width="8" height="13" viewBox="0 0 8 13" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path fill-rule="evenodd" clip-rule="evenodd" d="M6.75019 12.1051L7.68603 11.1692L2.86004 6.34323L7.68603 1.51724L6.75019 0.581398L0.988358 6.34323L6.75019 12.1051Z" fill="black"/>
                </svg>
              </button>
            `,
            nextArrow: `
              <button class="slide-arrow next-arrow">
                <span class="screenreader">Next</span>
                <svg width="8" height="13" viewBox="0 0 8 13" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path fill-rule="evenodd" clip-rule="evenodd" d="M1.24979 0.581417L0.313952 1.51726L5.13995 6.34325L0.313952 11.1692L1.24979 12.1051L7.01163 6.34325L1.24979 0.581417Z" fill="black"/>
                </svg>
              </button>
            `
          });
