 <style>

    .jepeh-fixed-footer {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      z-index: 99;
      display: flex;
      justify-content: space-evenly;
      align-items: center;
      gap: 8px;
      padding: 12px 0;
      background: linear-gradient(180deg,rgb(18, 18, 18) 0%, rgba(19, 0, 48, 1) 100%);
      border-top: 2px solid rgba(0, 0, 0, 0.5);
      box-shadow: 0 -3px 18px rgb(0 187 63),
                  inset 0 0 12px rgb(0 187 63);
      border-radius: 20px 20px 0 0;
      font-family: "Poppins", "Segoe UI", sans-serif;
      color: #eaffef;
    }
    
    /* === Tombol Footer === */
    .jepeh-fixed-footer a {
      flex: 1;
      max-width: 90px;
      text-align: center;
      text-decoration: none;
      color: #ffffff;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 4px;
      font-size: 13px;
      font-weight: 600;
      text-shadow: 0 0 6px #ff00dd, 0 0 12px #ff00dd;
      transition: all 0.25s ease-in-out;
    }
    
    /* Hover efek */
    .jepeh-fixed-footer a:hover {
