  async function fetchWithTimeout(resource, options = {}) {
    const { timeout = 30000 } = options;
    
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
  
    try {
      const response = await fetch(resource, {
        ...options,
        signal: controller.signal  
      });
      return response;
    } catch (error) {
      if (error.name === 'AbortError') {
        throw new Error('We’re having trouble connecting. It looks like the server is taking too long to respond. You can try refreshing the page or checking back in a few minutes');
      }
      throw error;
    } finally {
      clearTimeout(id);
    }
  }
</script>

